# 2025-08-18 DeepSeek-R1 版本：根据FHIR FSH定义从临床文本提取结构化数据
import re
import uuid
from datetime import datetime

class FHIRResourceBundleGenerator:
    def __init__(self, fhir_api_base: str):
        self.fhir_api_base = fhir_api_base

        # 呼吸系统症状映射表（症状词 → 标准编码）
        self.respiratory_symptoms_map = {
            '咳嗽': '咳嗽',
            '咳': '咳嗽',
            '胸闷': '胸闷',
            '胸痛': '胸闷',
            '气短': '气短',
            '气促': '气短',
            '气急': '气短',
            '呼吸困难': '呼吸困难',
            '喘憋': '呼吸困难',
            '喘息': '呼吸困难'
        }

        # 否定词列表（用于排除阴性症状）
        self.negative_indicators = ['无', '未', '否认', '没有', '不伴', '未出现', '未见', '未诉']

        # 身体部位映射
        self.body_site_map = {
            '肺': 'lung',
            '肺部': 'lung',
            '胸': 'chest',
            '胸腔': 'chest',
            '气管': 'trachea',
            '支气管': 'bronchus'
        }

    def _extract_respiratory_symptoms(self, text: str) -> list:
        """从文本中提取呼吸系统症状"""
        symptoms_found = []

        # 分割句子处理否定情况
        sentences = re.split(r'[，。；！？]', text)

        for sentence in sentences:
            has_negative = any(neg in sentence for neg in self.negative_indicators)

            # 检查每个症状词是否出现在句子中
            for symptom_word, symptom_code in self.respiratory_symptoms_map.items():
                if symptom_word in sentence and not has_negative:
                    # 提取相关身体部位
                    body_sites = []
                    for site_word, site_code in self.body_site_map.items():
                        if site_word in sentence:
                            body_sites.append({
                                "coding": [{
                                    "system": f"{self.fhir_api_base}/CodeSystem/cnwqk85-body-site-codes",
                                    "code": site_code,
                                    "display": site_word
                                }],
                                "text": site_word
                            })

                    symptoms_found.append({
                        "code": symptom_code,
                        "display": symptom_word,
                        "bodySites": body_sites,
                        "source_text": sentence.strip()
                    })
                    break  # 每个句子只记录一个主要症状

        return symptoms_found

    def _create_observation_resource(self, symptom_data: dict, 
                                    patient_id: str, 
                                    timestamp: str) -> dict:
        """创建符合Profile的Observation资源"""
        return {
            "resourceType": "Observation",
            "id": str(uuid.uuid1()),
            "meta": {
                "profile": [
                    f"{self.fhir_api_base}/StructureDefinition/cnwqk2"
                ]
            },
            "status": "final",
            "category": [{
                "coding": [{
                    "system": "http://terminology.hl7.org/CodeSystem/observation-category",
                    "code": "symptom",
                    "display": "症状"
                }]
            }],
            "code": {
                "coding": [{
                    "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk2",
                    "code": symptom_data["code"],
                    "display": symptom_data["display"]
                }],
                "text": symptom_data["display"]
            },
            "subject": {
                "reference": f"Patient/{patient_id}"
            },
            "effectiveDateTime": timestamp,
            "bodySite": symptom_data.get("bodySites", []),
            "text": {
                "status": "generated",
                "div": f"<div xmlns='http://www.w3.org/1999/xhtml'>"
                        f"文本摘录: {symptom_data['source_text']}</div>"
            }
        }

    def parse_clinical_text_to_fhir_bundle(self, patient_id, case_reports, ai_algorithm_type="nlp"):
        """解析临床文本生成FHIR Bundle"""
        bundle_entries = []

        # 处理每个病例报告
        for report in case_reports:
            # 只处理症状相关的报告类型
            if report.get("topic") not in ["主诉", "症状与体征", "现病史 发病及诊治经过"]:
                continue

            timestamp = report.get("timestamp", datetime.now().isoformat())
            text = report.get("text", "")

            # 提取呼吸系统症状
            symptoms = self._extract_respiratory_symptoms(text)

            # 为每个症状创建Observation资源
            for symptom in symptoms:
                obs_resource = self._create_observation_resource(
                    symptom, patient_id, timestamp
                )

                bundle_entries.append({
                    "resource": obs_resource,
                    "request": {
                        "method": "POST",
                        "url": "Observation"
                    }
                })

        # 构建FHIR Bundle
        fhir_bundle = {
            "resourceType": "Bundle",
            "type": "transaction",
            "total": len(bundle_entries),
            "entry": bundle_entries
        }

        return fhir_bundle

