# -*- coding: utf-8 -*-
import requests, datetime
# ***** 这个函数一定要有  *****
def get_paperless_doc_id(prid):
    url = f'http://127.0.0.1:3456/api/empi/mapping?source=FHIR_PATIENT&sourceId={prid}&target=PAPERLESS_NGX'
    try:
        data = requests.get(url).json()
        return data['targetId']
    except:
        return None
def get_patient_name(name_list):
    """提取患者姓名"""
    if not name_list:
        return "未知"
    name = name_list[0]
    family = name.get('family', '')
    given = ' '.join(name.get('given', []))
    return f"{family}{given}"

def get_data_from_fhir_database(fhir_service_base_url):
    # 检查FHIR服务是否可用
    fhir_api_metadata = fhir_service_base_url + '/metadata'
    try:
        metadata_response = requests.get(fhir_api_metadata)
        if metadata_response.status_code != 200:
            print("FHIR服务不可用")
            return None
    except requests.exceptions.RequestException as e:
        print(f"连接FHIR服务失败: {e}")
        return None

    # 定义呼吸系统症状代码
    respiratory_codes = [
        "http://localhost:3456/api/terminology/CodeSystem/cnwqk2|咳嗽",
        "http://localhost:3456/api/terminology/CodeSystem/cnwqk2|胸闷",
        "http://localhost:3456/api/terminology/CodeSystem/cnwqk2|气短",
        "http://localhost:3456/api/terminology/CodeSystem/cnwqk2|呼吸困难"
    ]

    # 查询有呼吸系统症状的Observation资源
    observations = []
    url = fhir_service_base_url + '/Observation'
    for code in respiratory_codes:
        params = {
            'code': code,
            '_count': 100
        }
        print(params)

        try:
            response = requests.get(url, params=params)
            print(response.url)
            if response.status_code != 200:
                print(f"查询Observation失败: {response.status_code}")
                break

            data = response.json()
            observations.extend(data.get('entry', []))


        except requests.exceptions.RequestException as e:
            print(f"查询过程中出错: {e}")


    # 提取有症状的患者ID
    patient_ids = set()
    for entry in observations:
        resource = entry.get('resource', {})
        subject = resource.get('subject', {})
        if subject.get('reference', '').startswith('Patient/'):
            patient_id = subject['reference'].split('/')[-1]
            patient_ids.add(patient_id)

    if not patient_ids:
        return []

    # 查询患者详细信息
    patients = []
    url = fhir_service_base_url + '/Patient'
    params = {
        '_id': ','.join(patient_ids),
        '_count': len(patient_ids)
    }

    try:
        response = requests.get(url, params=params)
        if response.status_code != 200:
            print(f"查询Patient失败: {response.status_code}")
            return []

        data = response.json()
        for entry in data.get('entry', []):
            patient = entry.get('resource', {})
            patient_id = patient.get('id', '')

            patients.append({
                'id': patient_id,
                'pxid': get_paperless_doc_id(patient_id),
                'name': get_patient_name(patient.get('name', [])),
                'gender': patient.get('gender', '未知'),
                'birthDate': patient.get('birthDate', ''),
                'detailsUrl': f"/app/timeline/patient?rid=Patient/{patient_id}"
            })

    except requests.exceptions.RequestException as e:
        print(f"获取患者信息失败: {e}")

    return patients

if __name__ == '__main__':
    fhir_api_base = "http://localhost:3456/api/fhir/baseDstu3"
    patient_data = get_data_from_fhir_database(fhir_api_base)

    if patient_data is None:
        print('执行过程中出现错误')
    else:
        if len(patient_data) == 0:
            print('没有查到符合标准的患者')
        else:
            print(f'有{len(patient_data)}名患者符合标准')
            # 打印前5名患者信息示例
            for i, patient in enumerate(patient_data[:5]):
                print(f"{i+1}. ID: {patient['id']}, 姓名: {patient['name']}, 性别: {patient['gender']}, 出生日期: {patient['birthDate']}")

