# 2024-06-10 DeepSeek-V3 本版本创建目的：从手术记录和病理报告中提取HCC诊断和R0切除状态信息，构建符合FHIR FSH定义的资源
import re
import uuid
import json
from datetime import datetime
from typing import List, Dict, Any, Optional

class FHIRResourceBundleGenerator:
    def __init__(self, fhir_api_base: str):
        self.fhir_api_base = fhir_api_base
        # 定义否定词列表及其作用范围
        self.negation_terms = ["无", "否认", "未", "没有", "不", "否", "从未", "未曾", "排除", "未发现", "未见到", "未进行"]
        self.negation_window_size = 5  # 否定词作用范围（词数）

        # 定义HCC诊断相关关键词
        self.hcc_keywords = ["肝细胞癌", "肝癌", "HCC", "肝占位", "肝恶性肿瘤", "C22.0", "8170/3"]

        # 定义手术相关关键词
        self.surgery_keywords = ["手术", "切除", "切除术", "肝切除", "肿瘤切除", "0FB00ZZ"]

        # 定义病理相关关键词
        self.pathology_keywords = ["病理", "活检", "病理检查", "病理报告", "病理诊断"]

        # 定义切缘状态关键词
        self.margin_negative_keywords = ["切缘阴性", "切缘未见癌", "切缘无癌", "切缘干净", "切缘未见肿瘤", "切缘无肿瘤", "切缘清晰"]
        self.margin_micro_positive_keywords = ["镜下切缘阳性", "切缘镜下见癌", "切缘镜下阳性", "镜下阳性"]
        self.margin_macro_positive_keywords = ["肉眼切缘阳性", "切缘肉眼见癌", "切缘肉眼阳性", "肉眼阳性"]

    def _contains_negation(self, text: str) -> bool:
        """检查文本中是否包含否定描述，考虑否定词的作用范围"""
        words = text.split()
        for i, word in enumerate(words):
            if word in self.negation_terms:
                # 检查否定词后的window_size个词内是否有相关关键词
                start = i
                end = min(i + self.negation_window_size, len(words))
                context = " ".join(words[start:end])
                # 如果否定词后跟相关关键词，则返回True
                if any(keyword in context for keyword in self.hcc_keywords + self.surgery_keywords + self.pathology_keywords):
                    return True
        return False

    def _extract_resection_from_surgery_record(self, text: str, timestamp: str) -> Optional[Dict[str, Any]]:
        """从手术记录中提取切除信息"""
        if self._contains_negation(text):
            return None

        # 检查是否包含手术关键词
        if not any(keyword in text for keyword in self.surgery_keywords):
            return None

        # 检查是否包含切除描述
        resection_keywords = ["切除", "切除术", "切除手术"]
        if not any(keyword in text for keyword in resection_keywords):
            return None

        return {
            "resection_performed": True,
            "time": timestamp,
            "text_excerpt": text[:100] + "..." if len(text) > 100 else text
        }

    def _determine_resection_status(self, text: str) -> Optional[str]:
        """根据病理报告文本判断切除状态"""
        # 检查阴性切缘关键词
        if any(keyword in text for keyword in self.margin_negative_keywords):
            return "R0"

        # 检查镜下阳性切缘关键词
        if any(keyword in text for keyword in self.margin_micro_positive_keywords):
            return "R1"

        # 检查肉眼阳性切缘关键词
        if any(keyword in text for keyword in self.margin_macro_positive_keywords):
            return "R2"

        # 如果都没有匹配，尝试使用正则表达式匹配R0/R1/R2
        status_match = re.search(r"\b(R[0-2])\b", text)
        if status_match:
            return status_match.group(1)

        return None

    def _extract_hcc_diagnosis_from_pathology(self, text: str, timestamp: str) -> Optional[Dict[str, Any]]:
        """从病理报告中提取HCC诊断信息"""
        if self._contains_negation(text):
            return None

        # 检查是否包含HCC关键词
        if not any(keyword in text for keyword in self.hcc_keywords):
            return None

        # 判断切除状态
        resection_status = self._determine_resection_status(text)

        return {
            "hcc_diagnosis": True,
            "resection_status": resection_status,
            "time": timestamp,
            "text_excerpt": text[:100] + "..." if len(text) > 100 else text
        }

    def _create_condition_resource(self, patient_id: str, diagnosis_info: Dict[str, Any]) -> Dict[str, Any]:
        """创建HCC诊断的Condition资源"""
        resource_id = str(uuid.uuid1())
        return {
            "resourceType": "Condition",
            "id": resource_id,
            "meta": {
                "profile": ["http://localhost:3456/api/terminology/Profile/cnwqk3-condition"]
            },
            "text": {
                "status": "generated",
                "div": f"<div xmlns=\"http://www.w3.org/1999/xhtml\">文本摘录：{diagnosis_info['text_excerpt']}</div>"
            },
            "clinicalStatus": {
                "coding": [{
                    "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
                    "code": "active",
                    "display": "active"
                }]
            },
            "verificationStatus": {
                "coding": [{
                    "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
                    "code": "confirmed",
                    "display": "confirmed"
                }]
            },
            "code": {
                "coding": [
                    {
                        "system": "http://localhost:3456/api/terminology/CodeSystem/icd10",
                        "code": "C22.0",
                        "display": "肝细胞癌"
                    },
                    {
                        "system": "http://localhost:3456/api/terminology/CodeSystem/icdo3",
                        "code": "8170/3",
                        "display": "肝细胞癌"
                    }
                ]
            },
            "subject": {
                "reference": f"Patient/{patient_id}"
            },
            "onsetDateTime": diagnosis_info.get('time')
        }

    def _create_procedure_resource(self, patient_id: str, procedure_info: Dict[str, Any]) -> Dict[str, Any]:
        """创建手术切除的Procedure资源"""
        resource_id = str(uuid.uuid1())
        # 映射切除状态代码
        status_map = {
            "R0": {"code": "R0", "display": "R0 Resection"},
            "R1": {"code": "R1", "display": "R1 Resection"},
            "R2": {"code": "R2", "display": "R2 Resection"}
        }
        status_code = status_map.get(procedure_info.get('resection_status', ''), {})

        return {
            "resourceType": "Procedure",
            "id": resource_id,
            "meta": {
                "profile": ["http://localhost:3456/api/terminology/Profile/cnwqk3-procedure"]
            },
            "text": {
                "status": "generated",
                "div": f"<div xmlns=\"http://www.w3.org/1999/xhtml\">文本摘录：{procedure_info['text_excerpt']}</div>"
            },
            "code": {
                "coding": [
                    {
                        "system": "http://localhost:3456/api/terminology/CodeSystem/icd10",
                        "code": "0FB00ZZ",
                        "display": "肝切除术"
                    }
                ]
            },
            "outcome": {
                "coding": [{
                    "system": "http://localhost:3456/api/terminology/CodeSystem/resection-status-cs",
                    "code": status_code.get("code", ""),
                    "display": status_code.get("display", "")
                }]
            },
            "subject": {
                "reference": f"Patient/{patient_id}"
            },
            "performedDateTime": procedure_info.get('time')
        }

    def parse_clinical_text_to_fhir_bundle(self, patient_id: str, case_reports: List[Dict[str, Any]], ai_algorithm_type: str = "nlp") -> Dict[str, Any]:
        """解析临床文本，生成FHIR Bundle"""
        entries = []

        # 分离手术记录和病理报告
        surgery_reports = [r for r in case_reports if r.get('topic') == '手术记录']
        pathology_reports = [r for r in case_reports if r.get('topic') == '辅助检查 病理']

        # 处理手术记录
        resection_info = None
        for report in surgery_reports:
            text = report.get('text', '')
            timestamp = report.get('timestamp', '')

            resection_info = self._extract_resection_from_surgery_record(text, timestamp)
            if resection_info:
                break  # 找到第一个有效的手术记录即可

        # 处理病理报告
        diagnosis_info = None
        for report in pathology_reports:
            text = report.get('text', '')
            timestamp = report.get('timestamp', '')

            diagnosis_info = self._extract_hcc_diagnosis_from_pathology(text, timestamp)
            if diagnosis_info and diagnosis_info.get('hcc_diagnosis') and diagnosis_info.get('resection_status') == 'R0':
                break  # 找到第一个有效的HCC诊断且R0切除的病理报告

        # 只有同时满足有切除手术和HCC诊断且R0切除，才生成资源
        if resection_info and diagnosis_info and diagnosis_info.get('hcc_diagnosis') and diagnosis_info.get('resection_status') == 'R0':
            # 创建Condition资源
            condition_resource = self._create_condition_resource(patient_id, diagnosis_info)
            entries.append({
                "resource": condition_resource,
                "request": {
                    "method": "POST",
                    "url": "Condition"
                }
            })

            # 创建Procedure资源，使用病理报告中的R0状态
            procedure_info = {
                "resection_status": diagnosis_info.get('resection_status'),
                "time": resection_info.get('time'),  # 使用手术时间
                "text_excerpt": f"手术记录: {resection_info.get('text_excerpt', '')}; 病理报告: {diagnosis_info.get('text_excerpt', '')}"
            }
            procedure_resource = self._create_procedure_resource(patient_id, procedure_info)
            entries.append({
                "resource": procedure_resource,
                "request": {
                    "method": "POST",
                    "url": "Procedure"
                }
            })

        # 构建Bundle
        bundle = {
            "resourceType": "Bundle",
            "type": "transaction",
            "total": len(entries),
            "entry": entries
        }

        return bundle

import re
import uuid
from datetime import datetime
from typing import List, Dict, Any, Optional, Tuple

class FHIRResourceBundleGenerator:
    def __init__(self, fhir_api_base: str):
        self.fhir_api_base = fhir_api_base

        # 更新正则表达式以更精确地识别手术类型
        self.priority_patterns = {
            "elective": re.compile(r'择期|计划|常规|定期|术前讨论|具备条件|拟行'),
            "emergency": re.compile(r'急诊|紧急|急症|急救|立即')
        }
        self.approach_patterns = {
            "thoracoscopic": re.compile(r'胸腔镜|腔镜|微创|单孔|多孔|VATS')
        }
        # 更精确的手术类型识别 - 区分肺切除术和肺大疱切除术
        self.procedure_patterns = {
            "pulmonary-lobectomy": re.compile(
                r'(肺(叶|段))?切除(术)?|'  # 修正括号配对问题
                r'(肺(叶|段))?切|'
                r'(肺(叶|段))?根治(术)?|'
                r'(肺(叶|段))?肿瘤切除|'
                r'(肺(叶|段))?癌根治|'
                r'(肺(叶|段))?楔形切除|'
                r'肺(叶|段)?切除术'
            ),
            "bullectomy": re.compile(r'肺大疱切除(术)?|肺大泡切除(术)?|肺疱切除(术)?')
        }
        # 更详细的解剖部位识别
        self.body_site_patterns = {
            "lung": re.compile(
                r'肺(叶|段)?|(左|右)(上|中|下)?肺(叶)?|'
                r'右上肺|右下肺|左上肺|左下肺|右中肺'
            )
        }
        # 特定解剖部位映射
        self.body_site_mapping = {
            "右上肺": "lung",
            "右下肺": "lung",
            "左上肺": "lung",
            "左下肺": "lung",
            "右中肺": "lung",
            "右肺": "lung",
            "左肺": "lung"
        }

    def _extract_priority(self, text: str) -> Optional[str]:
        """提取手术优先级 - 优化处理无明确优先级关键词的情况"""
        if self.priority_patterns["emergency"].search(text):
            return "emergency"
        # 无急诊关键词时默认为择期
        return "elective"

    def _extract_approach(self, text: str) -> Optional[str]:
        """提取手术入路 - 增强对胸腔镜的识别"""
        if self.approach_patterns["thoracoscopic"].search(text):
            return "thoracoscopic"
        return None

    def _extract_procedure(self, text: str) -> Optional[str]:
        """提取手术类型 - 更精确地区分肺切除术和肺大疱切除术"""
        # 首先排除肺大疱切除术
        if self.procedure_patterns["bullectomy"].search(text):
            return None  # 不符合肺切除术画像

        # 然后检查肺切除术
        if self.procedure_patterns["pulmonary-lobectomy"].search(text):
            return "pulmonary-lobectomy"

        return None

    def _extract_body_sites(self, text: str) -> List[Tuple[str, str]]:
        """
        提取解剖部位 - 增强对具体部位的识别
        返回格式: [(部位代码, 原始描述)]
        """
        sites = []

        # 首先尝试匹配具体部位
        for site_desc, site_code in self.body_site_mapping.items():
            if site_desc in text:
                sites.append((site_code, site_desc))

        # 如果没有匹配到具体部位，则尝试匹配一般描述
        if not sites and self.body_site_patterns["lung"].search(text):
            sites.append(("lung", "肺"))

        return sites

    def _extract_date(self, text: str) -> Optional[str]:
        """提取手术日期 - 增强日期格式处理"""
        # 尝试匹配ISO格式日期
        iso_pattern = re.compile(r'\d{4}-\d{2}-\d{2}')
        iso_match = iso_pattern.search(text)
        if iso_match:
            return iso_match.group() + "T00:00:00Z"

        # 尝试匹配中文格式日期
        date_pattern = re.compile(r'(\d{4})[年/-](\d{1,2})[月/-](\d{1,2})[日]?')
        match = date_pattern.search(text)
        if match:
            try:
                year, month, day = match.groups()
                dt = datetime(int(year), int(month), int(day))
                return dt.isoformat() + 'Z'
            except ValueError:
                return None

        # 尝试匹配只有月和日的日期
        month_day_pattern = re.compile(r'(\d{1,2})[月/-](\d{1,2})[日]?')
        month_day_match = month_day_pattern.search(text)
        if month_day_match:
            try:
                month, day = month_day_match.groups()
                # 假设是当前年
                year = datetime.now().year
                dt = datetime(int(year), int(month), int(day))
                return dt.isoformat() + 'Z'
            except ValueError:
                return None

        return None

    def _create_procedure_resource(
        self, 
        patient_id: str,
        text: str,
        timestamp: str,
        procedure_code: str,
        body_sites: List[Tuple[str, str]],
        priority: str,
        approach: str
    ) -> Dict[str, Any]:
        """创建符合FHIR Profile的Procedure资源 - 优化解剖部位处理"""
        # 创建扩展元素
        extensions = [
            {
                "url": "http://localhost:3456/api/terminology/StructureDefinition/cnwqk85-procedure-priority",
                "valueCodeableConcept": {
                    "coding": [{
                        "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk85-priority-codes",
                        "code": priority,
                        "display": "择期手术" if priority == "elective" else "急诊手术"
                    }]
                }
            },
            {
                "url": "http://localhost:3456/api/terminology/StructureDefinition/cnwqk85-surgical-approach",
                "valueCodeableConcept": {
                    "coding": [{
                        "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk85-approach-codes",
                        "code": approach,
                        "display": "胸腔镜"
                    }]
                }
            }
        ]

        # 创建bodySite元素 - 包含具体描述
        body_site_codings = []
        for site_code, site_desc in body_sites:
            body_site_codings.append({
                "coding": [{
                    "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk85-body-site-codes",
                    "code": site_code,
                    "display": site_desc
                }],
                "text": site_desc  # 保留原始描述文本
            })

        # 尝试从文本中提取具体手术日期
        performed_date = self._extract_date(text) or timestamp

        return {
            "resourceType": "Procedure",
            "id": str(uuid.uuid1()),
            "meta": {
                "profile": ["http://localhost:3456/api/terminology/Profile/cnwqk85-lung-resection"]
            },
            "status": "completed",
            "category": {
                "coding": [{
                    "system": "http://terminology.hl7.org/CodeSystem/procedure-category",
                    "code": "surgery",
                    "display": "外科手术"
                }]
            },
            "code": {
                "coding": [{
                    "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk85-procedure-codes",
                    "code": procedure_code,
                    "display": "肺切除术"
                }],
                "text": text.split("。")[0]  # 使用首句作为简要描述
            },
            "subject": {
                "reference": f"Patient/{patient_id}"
            },
            "performedDateTime": performed_date,
            "bodySite": body_site_codings,
            "extension": extensions,
            "note": [{
                "text": text  # 保留完整原始文本作为参考
            }]
        }

    def parse_clinical_text_to_fhir_bundle(
        self, 
        patient_id: str, 
        case_reports: List[Dict[str, str]], 
        ai_algorithm_type: str = "nlp"
    ) -> Dict[str, Any]:
        """解析临床文本并生成FHIR Bundle - 增强对阳性样本的处理"""
        entries = []

        for report in case_reports:
            # 扩展处理更多相关主题类型
            relevant_topics = ["手术记录", "放射治疗", "治疗 同期放化疗", "辅助检查", "体格检查"]
            if report.get("topic") not in relevant_topics:
                continue

            text = report.get("text", "")
            timestamp = report.get("timestamp", datetime.utcnow().isoformat() + "Z")

            # 提取关键信息 - 添加详细日志
            priority = self._extract_priority(text)
            approach = self._extract_approach(text)
            procedure = self._extract_procedure(text)
            body_sites = self._extract_body_sites(text)

            # 验证必要信息是否齐全
            if not all([priority, approach, procedure, body_sites]):
                continue

            # 创建FHIR Procedure资源
            procedure_resource = self._create_procedure_resource(
                patient_id=patient_id,
                text=text,
                timestamp=timestamp,
                procedure_code=procedure,
                body_sites=body_sites,
                priority=priority,
                approach=approach
            )

            # 添加到Bundle条目
            entries.append({
                "resource": procedure_resource,
                "request": {
                    "method": "POST",
                    "url": "Procedure"
                }
            })

        # 构建FHIR Bundle
        return {
            "resourceType": "Bundle",
            "type": "transaction",
            "total": len(entries),
            "entry": entries
        }

