def get_data_from_fhir_database(fhir_service_base_url):
    # 检查FHIR服务是否可用
    fhir_api_metadata = fhir_service_base_url + '/metadata'
    try:
        metadata_response = requests.get(fhir_api_metadata)
        if metadata_response.status_code != 200:
            print("FHIR服务不可用")
            return None
    except requests.exceptions.RequestException as e:
        print(f"连接FHIR服务失败: {str(e)}")
        return None

    # 构建Procedure资源搜索参数
    search_params = {
        '_profile': 'http://localhost:3456/api/terminology/Profile/cnwqk85-lung-resection',
        #'status': 'planned',
        '_sort': '-date',
        '_count': 100
    }

    # 获取所有符合条件的Procedure资源
    procedures = []
    next_url = fhir_service_base_url + '/Procedure'

    while next_url:
        try:
            response = requests.get(next_url, params=search_params)
            if response.status_code != 200:
                print(f"查询Procedure资源失败: HTTP {response.status_code}")
                return None

            bundle = response.json()
            if bundle.get('resourceType') != 'Bundle':
                print("响应不是有效的FHIR Bundle")
                return None
            print(procedures) 
            # 收集当前页的条目
            procedures.extend([entry['resource'] for entry in bundle.get('entry', []) 
                               if entry.get('resource', {}).get('resourceType') == 'Procedure'])

            # 检查是否有下一页
            next_link = next((link['url'] for link in bundle.get('link', []) 
                             if link.get('relation') == 'next'), None)
            next_url = next_link
            search_params = {}  # 后续分页URL已包含所有参数

        except requests.exceptions.RequestException as e:
            print(f"查询Procedure资源时出错: {str(e)}")
            return None
        except ValueError:
            print("解析JSON响应失败")
            return None

    # 提取符合条件的患者ID
    patient_ids = set()
    for procedure in procedures:
        # 验证手术类型为肺切除术
        procedure_code = procedure.get('code', {}).get('coding', [{}])[0].get('code')
        if procedure_code != 'pulmonary-lobectomy':
            continue

        # 验证手术优先级为择期
        priority_extension = next((ext for ext in procedure.get('extension', []) 
                                  if ext.get('url') == 'http://localhost:3456/api/terminology/StructureDefinition/cnwqk85-procedure-priority'), None)
        if not priority_extension:
            continue

        priority_code = priority_extension.get('valueCodeableConcept', {}).get('coding', [{}])[0].get('code')
        if priority_code != 'elective':
            continue

        # 验证手术入路为胸腔镜
        approach_extension = next((ext for ext in procedure.get('extension', []) 
                                  if ext.get('url') == 'http://localhost:3456/api/terminology/StructureDefinition/cnwqk85-surgical-approach'), None)
        if not approach_extension:
            continue

        approach_code = approach_extension.get('valueCodeableConcept', {}).get('coding', [{}])[0].get('code')
        if approach_code != 'thoracoscopic':
            continue

        # 提取患者ID
        subject_ref = procedure.get('subject', {}).get('reference', '')
        if subject_ref.startswith('Patient/'):
            patient_ids.add(subject_ref.split('/')[1])

    # 获取患者详细信息
    filtered_patients = []
    for patient_id in patient_ids:
        try:
            response = requests.get(f"{fhir_service_base_url}/Patient/{patient_id}")
            if response.status_code != 200:
                print(f"获取患者{patient_id}信息失败: HTTP {response.status_code}")
                continue

            patient = response.json()
            if patient.get('resourceType') != 'Patient':
                print(f"响应不是有效的Patient资源: {patient_id}")
                continue

            # 提取患者基本信息
            name_parts = []
            for name in patient.get('name', []):
                given = ' '.join(name.get('given', []))
                family = name.get('family', '')
                if given or family:
                    name_parts.append(f"{family}{given}")

            display_name = ', '.join(name_parts) if name_parts else '未知姓名'

            # 构建患者信息字典
            patient_info = {
                'id': patient_id,
                'pxid': get_paperless_doc_id(patient_id),
                'name': display_name,
                'birthDate': patient.get('birthDate', ''),
                'gender': patient.get('gender', 'unknown'),
                'detailsUrl': f"/app/timeline/patient?rid=Patient/{patient_id}"
            }

            filtered_patients.append(patient_info)

        except requests.exceptions.RequestException as e:
            print(f"获取患者{patient_id}信息时出错: {str(e)}")
        except ValueError:
            print(f"解析患者{patient_id}的JSON响应失败")

    return filtered_patients

if __name__ == '__main__':
    fhir_api_base = "http://localhost:3456/api/fhir/baseDstu4"
