            matches = re.finditer(pattern, text, re.IGNORECASE)
            for match in matches:
                value = float(match.group(1))
                glucose_data.append({
                    "type": "fasting",
                    "value": value,
                    "unit": "mmol/L",
                    "text": match.group(0)
                })

