        ogtt_patterns = [
            r"OGTT2小时[为是]?[：:]?\s*(\d+\.?\d*)\s*(mmol/L|mmol|毫摩尔)",
            r"糖耐量试验2小时[为是]?[：:]?\s*(\d+\.?\d*)\s*(mmol/L|mmol|毫摩尔)",
            r"口服葡萄糖耐量试验2小时[为是]?[：:]?\s*(\d+\.?\d*)\s*(mmol/L|mmol|毫摩尔)"
