        """
        从文本中提取糖尿病症状信息
        返回: 列表，包含提取到的症状信息字典
        """
        symptoms_data = []

        for symptom_type, keywords in self.symptom_keywords.items():
            for keyword in keywords:
                if keyword in text:
                    # 检查是否有否定词
                    negation_pattern = r"(无|没有|未发现|不存在|否认)\s*" + keyword
                    negation_match = re.search(negation_pattern, text)

                    if not negation_match:
                        symptoms_data.append({
                            "type": symptom_type,
                            "present": True,
                            "text": keyword
                        })
                        break  # 找到一种表达方式即可

        return symptoms_data

    def check_diagnostic_criteria(self, glucose_data, symptoms_data):
        """
        检查是否符合WHO 1999年2型糖尿病诊断标准
        返回: 符合的诊断标准列表
        """
        met_criteria = []

        # 检查随机血糖标准 (≥11.1mmol/L并伴有症状)
        random_glucose_met = any(
            g["type"] == "random" and g["value"] >= self.diagnostic_criteria["random_glucose"]
            for g in glucose_data
        )

        if random_glucose_met and symptoms_data:
            met_criteria.append("random-glucose-meets-criteria")

        # 检查空腹血糖标准 (≥7.0mmol/L)
        fasting_glucose_met = any(
            g["type"] == "fasting" and g["value"] >= self.diagnostic_criteria["fasting_glucose"]
            for g in glucose_data
        )

        if fasting_glucose_met:
            met_criteria.append("fasting-glucose-meets-criteria")

        # 检查OGTT 2小时血糖标准 (≥11.1mmol/L)
        ogtt_glucose_met = any(
            g["type"] == "ogtt_2h" and g["value"] >= self.diagnostic_criteria["ogtt_2h_glucose"]
            for g in glucose_data
        )

        if ogtt_glucose_met:
            met_criteria.append("ogtt-2h-meets-criteria")

        # 检查是否有症状
        if symptoms_data:
            met_criteria.append("symptoms-present")

        return met_criteria

    def create_observation(self, patient_id, obs_data, obs_type, timestamp):
        """
        创建Observation资源
        """
        obs_id = str(uuid.uuid1())

        # 根据观察类型设置不同的LOINC代码和显示文本
        if obs_type == "fasting":
            code = {
