                    "system": "http://loinc.org",
                    "code": "1558-6",
                    "display": "Fasting glucose [Mass/volume] in Serum or Plasma"
                }],
                "text": "空腹血糖"
            }
            value_quantity = {
                "value": obs_data["value"],
                "unit": "mmol/L",
                "system": "http://unitsofmeasure.org",
                "code": "mmol/L"
            }
            profile_url = "http://localhost:3456/api/terminology/Profile/cnwqk255-fasting-blood-glucose"

        elif obs_type == "random":
            code = {
                "coding": [{
                    "system": "http://loinc.org",
                    "code": "2339-0",
                    "display": "Glucose [Mass/volume] in Blood"
                }],
                "text": "随机血糖"
            }
            value_quantity = {
                "value": obs_data["value"],
                "unit": "mmol/L",
                "system": "http://unitsofmeasure.org",
                "code": "mmol/L"
            }
            profile_url = "http://localhost:3456/api/terminology/Profile/cnwqk255-random-blood-glucose"

        elif obs_type == "ogtt_2h":
