                "value": obs_data["value"],
                "unit": "mmol/L",
                "system": "http://unitsofmeasure.org",
                "code": "mmol/L"
            }
            profile_url = "http://localhost:3456/api/terminology/Profile/cnwqk255-ogtt-2h-blood-glucose"

        elif obs_type == "symptom":
            code = {
                "coding": [{
