    def create_condition(self, patient_id, met_criteria, evidence_refs, timestamp):
        """
        创建Condition资源
        """
        condition_id = str(uuid.uuid1())

        # 构建证据引用
        evidence = []
        for ref in evidence_refs:
            evidence.append({
                "detail": [{"reference": ref}]
            })

        # 构建扩展 - 符合的诊断标准
        extensions = []
        for criterion in met_criteria:
            extensions.append({
                "url": "http://localhost:3456/api/terminology/StructureDefinition/cnwqk255-diagnostic-criteria-meeting",
                "valueCodeableConcept": {
                    "coding": [{
                        "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk255-t2dm-dx-criteria-cs",
                        "code": criterion,
                        "display": {
                            "random-glucose-meets-criteria": "随机血糖符合诊断标准",
                            "fasting-glucose-meets-criteria": "空腹血糖符合诊断标准",
                            "ogtt-2h-meets-criteria": "OGTT2小时血糖符合诊断标准",
                            "symptoms-present": "存在典型糖尿病症状"
                        }[criterion]
                    }]
                }
            })

        # 构建Condition资源
        condition = {
            "resourceType": "Condition",
            "id": condition_id,
            "meta": {
                "profile": ["http://localhost:3456/api/terminology/Profile/cnwqk255-t2dm-diagnosis"]
            },
            "text": {
                "status": "generated",
                "div": f"<div xmlns='http://www.w3.org/1999/xhtml'>根据WHO 1999年标准，符合2型糖尿病诊断</div>"
            },
            "clinicalStatus": {
                "coding": [{
                    "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
                    "code": "active",
                    "display": "活跃"
                }]
            },
            "verificationStatus": {
                "coding": [{
                    "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
                    "code": "confirmed",
                    "display": "已确认"
                }]
            },
            "category": [{
                "coding": [{
                    "system": "http://terminology.hl7.org/CodeSystem/condition-category",
                    "code": "encounter-diagnosis",
                    "display": "就诊诊断"
                }]
            }],
            "code": {
                "coding": [
                    {
                        "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk255-t2dm-dx-conclusion-cs",
                        "code": "meets-who-1999-criteria",
                        "display": "符合WHO(1999)2型糖尿病诊断标准"
                    },
                    {
                        "system": "http://localhost:3456/api/terminology/CodeSystem/icd10",
                        "code": "E11.9",
                        "display": "2型糖尿病，未伴有并发症"
                    }
                ],
                "text": "2型糖尿病"
            },
            "subject": {
                "reference": f"Patient/{patient_id}"
            },
            "onsetDateTime": timestamp,
            "recordedDate": datetime.now().isoformat(),
            "evidence": evidence,
            "extension": extensions
        }

        return condition

    def parse_clinical_text_to_fhir_bundle(self, patient_id, case_reports, ai_algorithm_type="nlp"):
        """
        从临床文本中提取信息并构建FHIR Bundle
        """
        # 初始化资源列表
        resources = []
        evidence_refs = []  # 用于存储证据观察的引用

        # 提取所有血糖值和症状
        all_glucose_data = []
        all_symptoms_data = []

        for report in case_reports:
            timestamp = report.get("timestamp", datetime.now().isoformat())
            text = report.get("text", "")
            topic = report.get("topic", "")

            # 根据主题类型决定处理方式
            if topic in ["实验室检查", "辅助检查", "症状与体征", "现病史", "主诉"]:
                # 提取血糖值
                glucose_data = self.extract_glucose_values(text)
                for data in glucose_data:
                    data["timestamp"] = timestamp
                    data["source_text"] = text
                    all_glucose_data.append(data)

                # 提取症状
                symptoms_data = self.extract_symptoms(text)
                for data in symptoms_data:
                    data["timestamp"] = timestamp
                    data["source_text"] = text
                    all_symptoms_data.append(data)

        # 创建血糖观察资源
        for glucose_data in all_glucose_data:
            obs_type = glucose_data["type"]
            obs = self.create_observation(
                patient_id, 
                glucose_data, 
                obs_type, 
                glucose_data["timestamp"]
            )
            resources.append(obs)
            evidence_refs.append(f"Observation/{obs['id']}")

        # 创建症状观察资源
        for symptom_data in all_symptoms_data:
            obs = self.create_observation(
                patient_id, 
                symptom_data, 
                "symptom", 
                symptom_data["timestamp"]
            )
            resources.append(obs)
            evidence_refs.append(f"Observation/{obs['id']}")

        # 检查是否符合诊断标准
        met_criteria = self.check_diagnostic_criteria(all_glucose_data, all_symptoms_data)

        # 如果符合任何诊断标准，创建Condition资源
        if met_criteria:
            # 使用最早的时间戳作为发病时间
            onset_time = min(
                [g["timestamp"] for g in all_glucose_data] + 
                [s["timestamp"] for s in all_symptoms_data],
                default=datetime.now().isoformat()
            )

            condition = self.create_condition(
                patient_id, 
                met_criteria, 
                evidence_refs, 
                onset_time
            )
            resources.append(condition)

        # 构建Bundle
        bundle_id = str(uuid.uuid1())
        bundle = {
            "resourceType": "Bundle",
            "id": bundle_id,
            "type": "transaction",
            "total": len(resources),
            "entry": []
        }

        for resource in resources:
            bundle["entry"].append({
                "resource": resource,
                "request": {
                    "method": "POST",
                    "url": resource["resourceType"]
                }
            })

        return bundle

