# -*- coding: utf-8 -*-
import requests

def get_paperless_doc_id(prid):
    url = f'http://127.0.0.1:3456/api/empi/mapping?source=FHIR_PATIENT&sourceId={prid}&target=PAPERLESS_NGX'
    try:
        response = requests.get(url)
        response.raise_for_status()
        data = response.json()
        return data['targetId']
    except Exception as e:
        print(f"Failed to get paperless doc id for patient {prid}: {e}")
        return None

def get_data_from_fhir_database(fhir_service_base_url):
    # Check if FHIR service is ready
    fhir_api_metadata = fhir_service_base_url + '/metadata'
    try:
        metadata_response = requests.get(fhir_api_metadata)
        if metadata_response.status_code != 200:
            print("FHIR service is not ready")
            return None
    except requests.exceptions.RequestException as e:
        print(f"Failed to connect to FHIR service: {e}")
        return None

    profile_url = "http://localhost:3456/api/terminology/StructureDefinition/cnwqk255-t2dm-diagnosis"
    patients_set = set()
    next_url = fhir_service_base_url + '/Condition?_profile=' + profile_url

    while next_url:
        try:
            response = requests.get(next_url)
            if response.status_code != 200:
                print(f"Failed to search Condition: {response.status_code}")
                break
            bundle = response.json()
            for entry in bundle.get('entry', []):
                resource = entry.get('resource')
                if resource and resource['resourceType'] == 'Condition':
                    subject_ref = resource.get('subject', {}).get('reference', '')
                    if subject_ref.startswith('Patient/'):
                        patient_id = subject_ref.split('/')[1]
                        patients_set.add(patient_id)
            next_url = None
            for link in bundle.get('link', []):
                if link.get('relation') == 'next':
                    next_url = link.get('url')
                    break
        except requests.exceptions.RequestException as e:
            print(f"Request error: {e}")
            break

    result = []
    for patient_id in patients_set:
        pxid = get_paperless_doc_id(patient_id)
        result.append({
            'id': patient_id,
            'pxid': pxid,
            'detailsUrl': f"/app/timeline/patient?rid=Patient/{patient_id}"
        })
    return result

if __name__ == '__main__':
    fhir_api_base = "http://localhost:3456/api/fhir/baseDstu3"
    patient_data = get_data_from_fhir_database(fhir_api_base)
    if patient_data is None:
        print('Something wrong during execution')
    else:
        if len(patient_data) == 0:
            print('没有查到符合标准的患者')
        else:
            print(f'有{len(patient_data)}患者符合标准')

