            if topic not in smoking_topics:
                continue

            # 检查文本是否包含吸烟信息且无否定
            if not self.is_smoking_mentioned(text):
                continue

            # 提取每天吸烟支数
            new_text = text.replace(' ', '')
            cigarettes_per_day = self.extract_cigarettes_per_day(new_text)
