                "request": {
                    "method": "POST",
                    "url": "Observation"
                }
            }
            bundle["entry"].append(entry)

        bundle["total"] = len(bundle["entry"])
        return bundle

    def is_smoking_mentioned(self, text):
        """
        检查文本是否包含吸烟信息且无否定

        Args:
            text: 临床文本

        Returns:
            bool: 是否包含吸烟信息且无否定
        """
        # 吸烟相关关键词
        smoking_keywords = ['吸烟', '抽烟', '烟瘾', '烟草', '烟']

        # 否定词模式（考虑作用范围）
        negation_patterns = [
            r'无.{0,5}吸烟', r'不.{0,5}吸烟', r'未.{0,5}吸烟', 
            r'否认.{0,5}吸烟', r'没有.{0,5}吸烟', r'从未.{0,5}吸烟',
            r'戒烟', r'已戒', r'戒除'
        ]

        # 检查是否包含吸烟关键词
        has_smoking_keyword = any(keyword in text for keyword in smoking_keywords)
        if not has_smoking_keyword:
            return False

        # 检查是否有否定模式
        for pattern in negation_patterns:
            if re.search(pattern, text):
                return False

        return True

    def extract_cigarettes_per_day(self, text):
        """
        从文本中提取每天吸烟支数

        Args:
            text: 临床文本

        Returns:
            int: 每天吸烟支数，如果未提取到则返回None
        """
        # 匹配每天吸烟支数的模式
        patterns = [
            r'每天[吸抽]烟?[约]?(\d+)[支根]',
            r'[吸抽]烟[约]?(\d+)[支根]/天',
            r'烟量[约]?(\d+)[支根]/日',
            r'每日[吸抽]烟[约]?(\d+)[支根]',
            r'[吸抽]烟[约]?(\d+)[支根]每天',
            r'[吸抽]烟[约]?(\d+)[支根]/日',
            r'烟龄.*每天[吸抽]?[约]?(\d+)[支根]'
        ]

        for pattern in patterns:
            match = re.search(pattern, text)
            if match:
                try:
                    return int(match.group(1))
                except ValueError:
                    continue

        return None

    def extract_cessation_guarantee(self, text):
        """
        从文本中提取戒烟保证信息

        Args:
            text: 临床文本

        Returns:
            str: "can-guarantee" 或 "cannot-guarantee"，如果未提取到则返回None
        """
        # 不能保证的模式
        cannot_guarantee_patterns = [
            r'不能保证停止吸烟',
            r'无法停止吸烟',
            r'不能戒烟',
            r'无法保证戒烟',
            r'难以戒烟',
            r'不愿戒烟'
        ]

        # 能保证的模式
        can_guarantee_patterns = [
            r'能保证停止吸烟',
            r'保证停止吸烟',
            r'可以戒烟',
            r'愿意戒烟',
            r'同意戒烟'
        ]

        # 先检查不能保证的模式
        for pattern in cannot_guarantee_patterns:
            if re.search(pattern, text):
                return "cannot-guarantee"

        # 再检查能保证的模式
        for pattern in can_guarantee_patterns:
            if re.search(pattern, text):
                return "can-guarantee"

        return None

    def build_smoking_observation(self, patient_id, cigarettes_per_day, cessation_guarantee, timestamp, original_text):
        """
        构建吸烟状态Observation资源

        Args:
