    def _extract_nephropathy_info(self, text: str) -> List[Dict]:
        """从文本中提取自身免疫肾病信息"""
        findings = []

        for nephropathy_name, code_info in self.nephropathy_mapping.items():
            if nephropathy_name in text:
                findings.append({
                    "code": code_info["code"],
                    "system": code_info["system"],
                    "display": code_info["display"],
                    "text": nephropathy_name
                })

        return findings

    def _extract_kidney_site(self, text: str) -> List[Dict]:
        """从文本中提取肾脏部位信息"""
        sites = []

        for site_cn, site_en in self.kidney_site_keywords.items():
            if site_cn in text:
                sites.append({
                    "coding": [{
                        "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk465-body-site-codes",
                        "code": site_en.lower().replace(" ", "-"),
                        "display": site_cn
                    }],
                    "text": site_cn
                })

        return sites

    def _extract_date(self, text: str, default_date: str) -> str:
        """从文本中提取日期信息"""
        # 尝试匹配常见的日期格式
        date_patterns = [
            r"(\d{4}年\d{1,2}月\d{1,2}日)",
            r"(\d{4}-\d{1,2}-\d{1,2})",
            r"(\d{4}/\d{1,2}/\d{1,2})",
            r"(\d{4}年\d{1,2}月)"
        ]

        for pattern in date_patterns:
            match = re.search(pattern, text)
            if match:
                date_str = match.group(1)
                # 标准化日期格式
                try:
                    if "年" in date_str and "月" in date_str and "日" in date_str:
                        date_obj = datetime.strptime(date_str, "%Y年%m月%d日")
                    elif "年" in date_str and "月" in date_str:
                        date_obj = datetime.strptime(date_str, "%Y年%m月")
                    elif "-" in date_str:
                        date_obj = datetime.strptime(date_str, "%Y-%m-%d")
                    elif "/" in date_str:
                        date_obj = datetime.strptime(date_str, "%Y/%m/%d")

                    return date_obj.strftime("%Y-%m-%d")
                except:
                    continue

        return default_date

    def _create_procedure_resource(self, patient_id: str, text: str, timestamp: str) -> Dict:
        """创建肾活检Procedure资源"""
        procedure_id = str(uuid.uuid1())

        # 提取日期
        performed_date = self._extract_date(text, timestamp.split("T")[0] if timestamp else datetime.now().strftime("%Y-%m-%d"))

        return {
            "resourceType": "Procedure",
            "id": procedure_id,
            "meta": {
                "profile": [
                    "http://localhost:3456/api/terminology/Profile/cnwqk465-RenalBiopsyProcedureProfile"
                ]
            },
            "text": {
                "status": "generated",
                "div": f"<div xmlns=\"http://www.w3.org/1999/xhtml\">文本摘录：{text}</div>"
            },
            "status": "completed",
            "code": {
                "coding": [{
                    "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk465-RenalBiopsyProcedureCodeSystem",
                    "code": "renal-biopsy",
                    "display": "肾活检"
                }],
                "text": "肾活检"
            },
            "subject": {
                "reference": f"Patient/{patient_id}"
            },
            "performedDateTime": performed_date
        }

    def _create_condition_resource(self, patient_id: str, finding: Dict, text: str, timestamp: str) -> Dict:
        """创建自身免疫肾病Condition资源"""
        condition_id = str(uuid.uuid1())

        # 提取日期
        onset_date = self._extract_date(text, timestamp.split("T")[0] if timestamp else datetime.now().strftime("%Y-%m-%d"))

        # 提取肾脏部位
        body_site = self._extract_kidney_site(text)

        condition_resource = {
            "resourceType": "Condition",
            "id": condition_id,
            "meta": {
                "profile": [
                    "http://localhost:3456/api/terminology/Profile/cnwqk465-AutoimmuneNephropathyConditionProfile"
                ]
            },
            "text": {
                "status": "generated",
                "div": f"<div xmlns=\"http://www.w3.org/1999/xhtml\">文本摘录：{text}</div>"
            },
            "clinicalStatus": {
                "coding": [{
                    "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
                    "code": "active",
                    "display": "活跃"
                }]
            },
            "verificationStatus": {
                "coding": [{
                    "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
                    "code": "confirmed",
                    "display": "已确认"
                }]
            },
            "category": [{
                "coding": [{
                    "system": "http://terminology.hl7.org/CodeSystem/condition-category",
                    "code": "diagnosis",
                    "display": "诊断"
                }]
            }],
            "code": {
                "coding": [{
                    "system": finding["system"],
                    "code": finding["code"],
                    "display": finding["display"]
                }],
                "text": finding["text"]
            },
            "subject": {
                "reference": f"Patient/{patient_id}"
            },
            "onsetDateTime": onset_date
        }

        if body_site:
            condition_resource["bodySite"] = body_site

        return condition_resource

    def parse_clinical_text_to_fhir_bundle(self, patient_id, case_reports, ai_algorithm_type="nlp"):
        """从临床文本中提取信息并生成FHIR Bundle"""
        # 初始化资源列表
        resources = []

        # 处理每个病例报告
        for report in case_reports:
            text = report.get("text", "")
            timestamp = report.get("timestamp", "")
            topic = report.get("topic", "")

            # 只处理与肾病相关的主题
            relevant_topics = ["辅助检查", "医学诊断", "病理检查", "实验室检查"]
            if not any(t in topic for t in relevant_topics):
                continue

            # 提取肾活检信息
            if self._extract_biopsy_info(text):
                procedure_resource = self._create_procedure_resource(patient_id, text, timestamp)
                resources.append(procedure_resource)

            # 提取自身免疫肾病信息
            nephropathy_findings = self._extract_nephropathy_info(text)
            for finding in nephropathy_findings:
                condition_resource = self._create_condition_resource(patient_id, finding, text, timestamp)
                resources.append(condition_resource)

        # 构建Bundle
        bundle_id = str(uuid.uuid1())
        entries = []

        for resource in resources:
            entry = {
                "resource": resource,
                "request": {
                    "method": "POST",
                    "url": resource["resourceType"]
                }
            }
            entries.append(entry)

        bundle = {
            "resourceType": "Bundle",
            "id": bundle_id,
            "type": "transaction",
            "total": len(entries),
            "entry": entries
        }

        return bundle

