# -*- coding: utf-8 -*-
import requests, datetime  # 可以使用的外部包只有这2个

def get_paperless_doc_id(prid):
    url = f'http://127.0.0.1:3456/api/empi/mapping?source=FHIR_PATIENT&sourceId={prid}&target=PAPERLESS_NGX'
    data = requests.get(url).json()
    return data['targetId']

def get_data_from_fhir_database(fhir_service_base_url):
    # Check if FHIR service is ready
    fhir_api_metadata = fhir_service_base_url + '/metadata'
    try:
        metadata_response = requests.get(fhir_api_metadata)
        if metadata_response.status_code != 200:
            print("FHIR service is not ready")
            return None
    except requests.exceptions.RequestException:
        print("Failed to connect to FHIR service")
        return None

    # 搜索符合肾活检条件的Procedure
    renal_biopsy_profile = "http://localhost:3456/api/terminology/Profile/cnwqk465-RenalBiopsyProcedureProfile"
    procedure_url = f"{fhir_service_base_url}/Procedure?_profile={renal_biopsy_profile}"

    try:
        procedure_response = requests.get(procedure_url)
        if procedure_response.status_code != 200:
            print(f"Failed to fetch procedures: {procedure_response.status_code}")
            return None

        procedure_bundle = procedure_response.json()
        if 'entry' not in procedure_bundle:
            print("No renal biopsy procedures found")
            return []

        # 获取所有进行过肾活检的患者ID
        patient_ids = set()
        for entry in procedure_bundle['entry']:
            resource = entry['resource']
            if 'subject' in resource and 'reference' in resource['subject']:
                patient_ref = resource['subject']['reference']
                if patient_ref.startswith('Patient/'):
                    patient_ids.add(patient_ref.split('/')[1])

        # 搜索这些患者的自身免疫肾病诊断
        autoimmune_profile = "http://localhost:3456/api/terminology/Profile/cnwqk465-AutoimmuneNephropathyConditionProfile"
        filtered_patients = []

        for patient_id in patient_ids:
            condition_url = f"{fhir_service_base_url}/Condition?subject=Patient/{patient_id}&_profile={autoimmune_profile}"
            condition_response = requests.get(condition_url)

            if condition_response.status_code == 200:
                condition_bundle = condition_response.json()
                if 'entry' in condition_bundle and len(condition_bundle['entry']) > 0:
                    # 获取患者详细信息
                    patient_url = f"{fhir_service_base_url}/Patient/{patient_id}"
                    patient_response = requests.get(patient_url)

                    if patient_response.status_code == 200:
                        patient_data = patient_response.json()

                        # 提取患者信息
                        patient_info = {
                            'prid': f"Patient/{patient_id}",
                            'name': '',
                            'gender': patient_data.get('gender', ''),
                            'birthDate': patient_data.get('birthDate', ''),
                            'pxid': get_paperless_doc_id(patient_id)
                        }

                        # 获取患者姓名
                        if 'name' in patient_data and len(patient_data['name']) > 0:
                            name = patient_data['name'][0]
                            if 'text' in name:
                                patient_info['name'] = name['text']
                            elif 'family' in name and 'given' in name:
                                patient_info['name'] = f"{name['family']} {''.join(name['given'])}"

                        # 添加详情URL
                        patient_info['detailsUrl'] = f"/app/timeline/patient?rid=Patient/{patient_id}"

                        filtered_patients.append(patient_info)

        return filtered_patients

    except Exception as e:
        print(f"Error during FHIR data retrieval: {str(e)}")
        return None

if __name__ == '__main__':
    fhir_api_base = "http://localhost:3456/api/fhir/baseDstu3"
    patient_data = get_data_from_fhir_database(fhir_api_base)
    if patient_data is None:
        print('something wrong during execution')
    else:
        if len(patient_data) == 0:
            print('没有查到符合标准的患者')
        else:
            print(f'有{len(patient_data)}患者符合标准')

