import re
import uuid
import json
from datetime import datetime
from typing import List, Dict, Any, Optional

class FHIRResourceBundleGenerator:
    def __init__(self, fhir_api_base: str):
        self.fhir_api_base = fhir_api_base
        # 定义代码系统URL
        self.diagnosis_cs_url = "http://localhost:3456/api/terminology/CodeSystem/cnwqk475-DiagnosisCS"
        self.cause_cs_url = "http://localhost:3456/api/terminology/CodeSystem/cnwqk475-CauseCS"
        self.duration_cs_url = "http://localhost:3456/api/terminology/CodeSystem/cnwqk475-DurationCS"

        # 定义值集URL
        self.pain_vs_url = "http://localhost:3456/api/terminology/ValueSet/cnwqk475-SpinalChronicPainVS"
        self.cause_vs_url = "http://localhost:3456/api/terminology/ValueSet/cnwqk475-SpinalCauseVS"
        self.duration_vs_url = "http://localhost:3456/api/terminology/ValueSet/cnwqk475-DurationVS"

        # 定义扩展URL
        self.pain_cause_ext_url = "http://localhost:3456/api/terminology/StructureDefinition/cnwqk475-pain-cause"
        self.pain_duration_ext_url = "http://localhost:3456/api/terminology/StructureDefinition/cnwqk475-pain-duration"

        # 定义Profile URL
        self.profile_url = "http://localhost:3456/api/terminology/Profile/cnwqk475-SpinalChronicPainDiagnosis"

        # 关键词映射
        self.cause_keywords = {
            "spinal_degeneration": ["退变", "退化", "退行性", "椎间盘突出", "骨质增生", "骨刺", "腰椎间盘"],
            "spinal_injury": ["损伤", "外伤", "骨折", "扭伤", "挫伤", "撞伤", "摔伤"],
            "spinal_inflammation": ["炎症", "炎性", "强直性脊柱炎", "脊柱结核", "感染"],
            "spinal_deformity": ["畸形", "侧弯", "脊柱侧凸", "驼背", "后凸"],
            "spinal_tumor": ["肿瘤", "瘤", "癌", "占位", "转移"]
        }

        # 持续时间关键词
        self.duration_keywords = ["个月", "月余", "多月", "半年", "年", "余年", "长期", "慢性"]

    def _extract_pain_cause(self, text: str) -> Optional[Dict]:
        """从文本中提取疼痛原因"""
        found_causes = []

        for cause_code, keywords in self.cause_keywords.items():
            for keyword in keywords:
                if keyword in text:
                    found_causes.append({
                        "code": cause_code,
                        "display": self._get_cause_display(cause_code),
                        "text": self._extract_context(text, keyword)
                    })
                    break  # 找到一种原因就跳出内层循环

        if found_causes:
            # 返回第一个找到的原因
            return found_causes[0]
        return None

    def _get_cause_display(self, cause_code: str) -> str:
        """根据原因代码获取显示文本"""
        displays = {
            "spinal_degeneration": "脊柱退变",
            "spinal_injury": "脊柱损伤",
            "spinal_inflammation": "脊柱炎症",
            "spinal_deformity": "脊柱畸形",
            "spinal_tumor": "脊柱肿瘤"
        }
        return displays.get(cause_code, "")

    def _extract_duration(self, text: str) -> Optional[Dict]:
        """从文本中提取疼痛持续时间"""
        # 查找持续时间模式
        duration_patterns = [
            r'(\d+)\s*个?月',
            r'(\d+)\s*年',
            r'半年',
            r'多月',
            r'长期',
            r'慢性'
        ]

        for pattern in duration_patterns:
            match = re.search(pattern, text)
            if match:
                duration_text = match.group(0)

                # 检查是否满足≥3个月的条件
                if self._is_duration_geq_3_months(duration_text):
                    return {
                        "code": "more_than_3_months",
                        "display": "大于等于3个月",
                        "text": duration_text
                    }

        return None

    def _is_duration_geq_3_months(self, duration_text: str) -> bool:
        """检查持续时间是否≥3个月"""
        # 提取数字
        num_match = re.search(r'(\d+)', duration_text)
        if num_match:
            num = int(num_match.group(1))
            if '年' in duration_text:
                return num * 12 >= 3
            elif '月' in duration_text:
                return num >= 3
            elif '半年' in duration_text:
                return 6 >= 3  # 半年是6个月
        else:
            # 没有明确数字，但包含"长期"、"慢性"等关键词
