        self.fhir_api_base = fhir_api_base

        # 否定词列表
        self.negation_terms = ["无", "否认", "未", "没有", "不", "否", "从未", "从来没", "从来没"]

        # 腰痛相关关键词
        self.low_back_pain_terms = ["腰痛", "腰疼", "腰部疼痛", "腰背痛", "腰椎痛"]

        # 持续时间提取模式
        self.duration_patterns = [
            r"持续(\d+)[个]?月",
            r"(\d+)[个]?月以上",
            r"(\d+)[个]?多月",
            r"长达(\d+)[个]?月",
            r"已有(\d+)[个]?月"
        ]

    def _contains_negation(self, text: str, target_phrase: str) -> bool:
        """检查文本中是否包含对目标短语的否定"""
        # 查找目标短语的位置
        target_match = re.search(target_phrase, text)
        if not target_match:
            return False

        target_start = target_match.start()

        # 查找否定词
        for negation in self.negation_terms:
            negation_matches = list(re.finditer(negation, text))
            for match in negation_matches:
                # 检查否定词是否在目标短语前且距离较近（假设作用范围为20个字符）
                if match.start() < target_start and (target_start - match.end()) <= 20:
                    return True

        return False

    def _extract_duration(self, text: str) -> int:
        """从文本中提取持续时间（月）"""
        for pattern in self.duration_patterns:
            matches = re.findall(pattern, text)
            if matches:
                try:
                    return int(matches[0])
                except (ValueError, IndexError):
                    continue
        return 0

    def parse_clinical_text_to_fhir_bundle(self, patient_id, case_reports, ai_algorithm_type="nlp"):
        """从临床文本解析并生成FHIR Bundle"""

        # 初始化Bundle
        bundle = {
            "resourceType": "Bundle",
            "type": "transaction",
            "total": 0,
            "entry": []
        }

        # 遍历所有病例报告
        for report in case_reports:
            # 只处理与症状相关的报告
            if report.get("topic") not in ["症状与体征", "症状体征", "主诉"]:
                continue

            text = report.get("text", "")
            timestamp = report.get("timestamp", "")

            # 检查文本是否包含腰痛描述
            has_low_back_pain = False
            pain_phrase = ""

            for pain_term in self.low_back_pain_terms:
                if pain_term in text:
                    # 检查是否被否定
                    if not self._contains_negation(text, pain_term):
                        has_low_back_pain = True
                        pain_phrase = pain_term
                        break

            if not has_low_back_pain:
                continue

            # 提取持续时间
            duration = self._extract_duration(text)
            if duration < 3:  # 不符合最小持续时间要求
                continue

            # 生成Observation资源
            observation_id = str(uuid.uuid1())

            # 构建文本摘录
            text_excerpt = f"文本摘录：患者主诉'{text}'。从中提取到腰痛症状，持续{duration}个月。"

            observation = {
                "resourceType": "Observation",
                "id": observation_id,
                "text": {
                    "status": "generated",
                    "div": f"<div xmlns=\"http://www.w3.org/1999/xhtml\">{text_excerpt}</div>"
                },
                "meta": {
                    "profile": [
                        "http://localhost:3456/api/terminology/Profile/cnwqk585-symptom-profile"
                    ]
                },
                "status": "final",
                "category": [
                    {
                        "coding": [
                            {
                                "system": "http://terminology.hl7.org/CodeSystem/observation-category",
                                "code": "symptom",
                                "display": "症状"
                            }
                        ]
                    }
                ],
                "code": {
                    "coding": [
                        {
                            "system": "http://localhost:3456/api/terminology/CodeSystem/icd10",
                            "code": "M54.5",
                            "display": "腰痛"
                        }
                    ],
                    "text": pain_phrase
                },
                "subject": {
                    "reference": f"Patient/{patient_id}"
                },
                "effectiveDateTime": timestamp if timestamp else datetime.now().isoformat(),
                "component": [
                    {
                        "code": {
                            "coding": [
                                {
                                    "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk585-symptom-component-cs",
                                    "code": "duration",
                                    "display": "症状持续时间"
                                }
                            ]
                        },
                        "valueQuantity": {
                            "value": duration,
                            "unit": "月",
                            "system": "http://unitsofmeasure.org",
                            "code": "mo"
                        }
                    }
                ]
            }

            # 添加到Bundle
            bundle_entry = {
                "resource": observation,
                "request": {
                    "method": "POST",
                    "url": "Observation"
                }
            }

            bundle["entry"].append(bundle_entry)

        # 更新Bundle总数
        bundle["total"] = len(bundle["entry"])

        return bundle

