# -*- coding: utf-8 -*-
import requests, datetime
from typing import Dict, Optional, List

# ***** 这个函数一定要有  *****
def get_paperless_doc_id(prid):
    url = f'http://127.0.0.1:3456/api/empi/mapping?source=FHIR_PATIENT&sourceId={prid}&target=PAPERLESS_NGX'
    try:
        response = requests.get(url)
        if response.status_code == 200:
            data = response.json()
            return data.get('targetId', '')
        else:
            print(f"Failed to get paperless doc ID for patient {prid}: {response.status_code}")
            return ''
    except Exception as e:
        print(f"Error getting paperless doc ID for patient {prid}: {str(e)}")
        return ''

def get_data_from_fhir_database(fhir_service_base_url, anchor_dates: Optional[Dict[str, str]] = {}):
    """
    接受包含不同锚点时间，用于计算，如果锚点时间为空，那么使用程序当前运行时间

    参数:
    anchor_dates (Dict[str, str]): 包含不同时间参考的字典，格式为:
        {
            "主诉": "YYYY-MM-DD",  # 播种时间
        }
        至少需要提供一个时间参考
    """

    # Check if FHIR service is ready
    fhir_api_metadata = fhir_service_base_url + '/metadata'
    try:
        metadata_response = requests.get(fhir_api_metadata)
        if metadata_response.status_code != 200:
            print("FHIR service is not ready")
            return []
    except requests.exceptions.RequestException as e:
        print(f"Failed to connect to FHIR service: {str(e)}")
        return []

    # 搜索符合症状标准的Observation
    params = {
        '_profile': 'http://localhost:3456/api/terminology/Profile/cnwqk585-symptom-profile',
        'code': 'http://localhost:3456/api/terminology/CodeSystem/icd10|M54.5',
        '_include': 'Observation:subject'
    }

    try:
        response = requests.get(fhir_service_base_url + '/Observation', params=params)
        if response.status_code != 200:
            print(f"Failed to search Observations: {response.status_code}")
            return []

        bundle = response.json()
        observations = [entry['resource'] for entry in bundle.get('entry', []) if entry.get('resource', {}).get('resourceType') == 'Observation']

        # 过滤出符合持续时间条件的Observation
        filtered_observations = []
        for obs in observations:
            # 检查组件中的持续时间
            for component in obs.get('component', []):
                code = component.get('code', {}).get('coding', [{}])[0].get('code')
                if code == 'duration':
                    value_quantity = component.get('valueQuantity', {})
                    value = value_quantity.get('value')
                    unit = value_quantity.get('unit')

                    # 检查持续时间是否满足条件（>=3个月）
                    if value is not None and unit == '月' and float(value) >= 3:
                        filtered_observations.append(obs)
                        break

        # 提取患者ID并去重
        patient_ids = set()
        for obs in filtered_observations:
            subject_ref = obs.get('subject', {}).get('reference', '')
            if subject_ref.startswith('Patient/'):
                patient_ids.add(subject_ref.split('/')[1])

        # 获取患者详细信息
        filtered_patients = []
        for patient_id in patient_ids:
            patient_response = requests.get(fhir_service_base_url + f'/Patient/{patient_id}')
            if patient_response.status_code == 200:
                patient_data = patient_response.json()

                # 获取paperless_ngx_document_id
                pxid = get_paperless_doc_id(patient_id)

                # 构建患者信息
                patient_info = {
                    'id': patient_id,
                    'pxid': pxid,
                    'detailsUrl': f"/app/timeline/patient?rid=Patient/{patient_id}",
                    'name': '',
                    'birthDate': patient_data.get('birthDate', ''),
                    'gender': patient_data.get('gender', '')
                }

                # 提取患者姓名
                names = patient_data.get('name', [])
                if names and len(names) > 0:
                    name_parts = []
                    given_names = names[0].get('given', [])
                    family_name = names[0].get('family', '')

                    if given_names:
                        name_parts.extend(given_names)
                    if family_name:
                        name_parts.append(family_name)

                    patient_info['name'] = ' '.join(name_parts)

                filtered_patients.append(patient_info)

        return filtered_patients

    except Exception as e:
        print(f"Error during FHIR data retrieval: {str(e)}")
        return []

if __name__ == '__main__':
    fhir_api_base = "http://localhost:3456/api/fhir/baseDstu4"
    patient_data = get_data_from_fhir_database(fhir_api_base)
    if patient_data is None:
        print('something wrong during execution')
    else:
        if len(patient_data) == 0:
            print('没有查到符合标准的患者')
        else:
            print(f'有{len(patient_data)}患者符合标准')
            for patient in patient_data:
                print(f"患者ID: {patient['id']}, 姓名: {patient['name']}, 文档ID: {patient['pxid']}")

