# 2024-06-01 DeepSeek-V3 本代码用于从患者医疗文档中提取肝功能测试信息并生成FHIR Bundle
import uuid
import re
import json
from datetime import datetime

class FHIRResourceBundleGenerator:
    def __init__(self, fhir_api_base: str):
        self.fhir_api_base = fhir_api_base
        # 否定词汇列表，用于检测否定描述
        self.negation_terms = ["否认", "无", "未", "没有", "不", "正常", "阴性", "未见异常", "排除"]
        # 肝功能测试关键词映射到代码系统
        self.test_keywords = {
            "总胆红素": {"code": "total_bilirubin", "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk625-laboratory-tests-cs"},
            "丙氨酸氨基转移酶": {"code": "alt", "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk625-laboratory-tests-cs"},
            "ALT": {"code": "alt", "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk625-laboratory-tests-cs"},
            "天冬氨酸氨基转移酶": {"code": "ast", "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk625-laboratory-tests-cs"},
            "AST": {"code": "ast", "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk625-laboratory-tests-cs"}
        }
        # 默认参考范围（单位依赖），如果文本中未提取到，则使用这些默认值（但优先从文本提取）
        self.default_reference_ranges = {
            "total_bilirubin": {"low": 0, "high": 21, "unit": "umol/L"},
            "alt": {"low": 0, "high": 40, "unit": "U/L"},
            "ast": {"low": 0, "high": 40, "unit": "U/L"}
        }
        # 单位映射：将文本中常见的单位映射到标准单位
        self.unit_mapping = {
            "umol/L": ["umol/L", "μmol/L", "mol/L"],
            "U/L": ["U/L", "IU/L"]
        }

    def _contains_negation(self, text, test_name):
        """检查文本中测试名称附近是否有否定词汇"""
        # 构建测试名称的模式，允许一些变体
        test_pattern = re.compile(test_name)
        # 查找测试名称的位置
        match = test_pattern.search(text)
        if not match:
            return False
        start_pos = match.start()
        end_pos = match.end()
        # 检查测试名称前后一定窗口大小（例如50个字符）内的否定词汇
        window_size = 50
        window_start = max(0, start_pos - window_size)
        window_end = min(len(text), end_pos + window_size)
        window_text = text[window_start:window_end]
        # 检查否定词汇
        for term in self.negation_terms:
            if term in window_text:
                return True
        return False

    def _extract_value_and_unit(self, text, test_name):
        """从文本中提取数值和单位"""
        # 模式：测试名称后跟数值和单位
        pattern = re.compile(rf"{test_name}[\s:：]*([\d.]+)\s*([^，。\s]+)")
        match = pattern.search(text)
        if match:
            value = float(match.group(1))
            unit = match.group(2)
            # 标准化单位
            for std_unit, variants in self.unit_mapping.items():
                if unit in variants:
                    unit = std_unit
                    break
            return value, unit
        return None, None

    def _extract_reference_range(self, text, test_name):
        """从文本中提取参考范围"""
        # 模式：参考范围可能以多种形式出现，例如“正常范围：0-40”或“参考值：0~40”
        patterns = [
            re.compile(rf"{test_name}[\s:：]*参考值[：:]*\s*([\d.]+)\s*[-~至]\s*([\d.]+)\s*([^，。\s]+)"),
            re.compile(rf"正常范围[：:]*\s*([\d.]+)\s*[-~至]\s*([\d.]+)\s*([^，。\s]+)"),
            re.compile(rf"{test_name}[\s:：]*正常值[：:]*\s*([\d.]+)\s*[-~至]\s*([\d.]+)\s*([^，。\s]+)")
        ]
        for pattern in patterns:
            match = pattern.search(text)
            if match:
                low = float(match.group(1))
                high = float(match.group(2))
                unit = match.group(3)
                # 标准化单位
                for std_unit, variants in self.unit_mapping.items():
                    if unit in variants:
                        unit = std_unit
                        break
                return low, high, unit
        return None, None, None

    def parse_clinical_text_to_fhir_bundle(self, patient_id, case_reports, ai_algorithm_type="nlp"):
        # 初始化Bundle
        bundle = {
            "resourceType": "Bundle",
            "type": "transaction",
            "total": 0,
            "entry": []
        }
        entries = []

        for report in case_reports:
            topic = report.get("topic", "")
            text = report.get("text", "")
            timestamp = report.get("timestamp", "")
            # 只处理实验室检查相关的topic
            if topic not in ["实验室检查", "辅助检查"]:
                continue

            # 遍历所有关注的测试
            for test_display, test_info in self.test_keywords.items():
                test_code = test_info["code"]
                system = test_info["system"]
                # 检查是否包含否定
                if self._contains_negation(text, test_display):
                    continue  # 跳过否定描述的测试

                # 提取数值和单位
                value, unit = self._extract_value_and_unit(text, test_display)
                if value is None:
                    continue  # 没有提取到数值，跳过

                # 提取参考范围，如果文本中没有，则使用默认值（但注意单位一致性）
                low, high, range_unit = self._extract_reference_range(text, test_display)
                if low is None or high is None:
                    # 使用默认参考范围，但确保单位一致
                    default_range = self.default_reference_ranges.get(test_code)
                    if default_range and unit == default_range["unit"]:
                        low = default_range["low"]
                        high = default_range["high"]
                    else:
                        continue  # 没有参考范围且单位不匹配默认值，跳过

                # 构建Observation资源
                observation_id = str(uuid.uuid1())
                observation = {
                    "resourceType": "Observation",
                    "id": observation_id,
                    "text": {
                        "status": "generated",
                        "div": f"<div xmlns=\"http://www.w3.org/1999/xhtml\">文本摘录：{text}。提取信息：{test_display} {value} {unit}，参考范围：{low}-{high} {unit}</div>"
                    },
                    "meta": {
                        "profile": ["http://localhost:3456/api/terminology/Profile/cnwqk625-liver-function-tests"]
                    },
                    "status": "final",
                    "code": {
                        "coding": [{
                            "system": system,
                            "code": test_code,
                            "display": test_display
                        }]
                    },
                    "subject": {
                        "reference": f"Patient/{patient_id}"
                    },
                    "effectiveDateTime": timestamp,
                    "valueQuantity": {
                        "value": value,
                        "unit": unit,
                        "system": "http://unitsofmeasure.org"
                    },
                    "referenceRange": [{
                        "type": {
                            "coding": [{
                                "system": "http://hl7.org/fhir/referencerange-meaning",
                                "code": "normal"
                            }]
                        },
                        "low": {
                            "value": low,
                            "unit": unit,
                            "system": "http://unitsofmeasure.org"
                        },
                        "high": {
                            "value": high,
                            "unit": unit,
                            "system": "http://unitsofmeasure.org"
                        }
                    }]
                }
                # 创建Bundle entry
                entry = {
                    "resource": observation,
                    "request": {
                        "method": "POST",
                        "url": "Observation"
                    }
                }
                entries.append(entry)

        bundle["entry"] = entries
        bundle["total"] = len(entries)
        return bundle

# 以下是生成的程序被调用的方法（预定义框架，无需修改）
if __name__ == "__main__":
    # 示例调用（用于测试）
    generator = FHIRResourceBundleGenerator("http://localhost:3456")
    patient_id = "example-patient-id"
    case_reports = [
        {
            "timestamp": "2023-01-01T10:00:00Z",
            "topic": "实验室检查",
            "text": "总胆红素：15 umol/L（正常范围：0-21 umol/L），ALT：30 U/L（参考值：0-40 U/L），AST：25 U/L。"
        }
    ]
    bundle = generator.parse_clinical_text_to_fhir_bundle(patient_id, case_reports)
    print(json.dumps(bundle, ensure_ascii=False, indent=2))

