    try:
        data = requests.get(url).json()
        return data.get('targetId', '')
    except:
        return ''

def filter_resources_without_reference_date_system(fhir_service_base_url):
    """获取所有符合肝功能测试Profile的Observation资源"""
    observations = []
    url = f"{fhir_service_base_url}/Observation?_profile=http://localhost:3456/api/terminology/Profile/cnwqk625-liver-function-tests"

    while url:
        try:
            response = requests.get(url)
            if response.status_code != 200:
                break

            bundle = response.json()
            if 'entry' in bundle:
                observations.extend([entry['resource'] for entry in bundle['entry'] if 'resource' in entry])

            # 检查是否有下一页
            next_links = [link for link in bundle.get('link', []) if link.get('relation') == 'next']
            url = next_links[0]['url'] if next_links else None
        except:
            break

    return observations

def get_data_from_fhir_database(fhir_service_base_url, anchor_dates: Optional[Dict[str, str]] = {}):
    # Check if FHIR service is ready
    fhir_api_metadata = fhir_service_base_url + '/metadata'
    try:
        metadata_response = requests.get(fhir_api_metadata)
        if metadata_response.status_code != 200:
            print("FHIR service is not ready")
            return []
    except requests.exceptions.RequestException:
        print("Failed to connect to FHIR service")
        return []

    # 临床研究标准
    ct_criterion = {
        "id": "s1876",
        "label": "Laboratory Examinations",
        "text_Chinese": "某次就医期间总胆红素在正常范围上限1.5倍以内，丙氨酸氨基转移酶（ALT）和天冬氨酸氨基转移酶（AST）在正常范围上限3倍以内的患者。",
        "text_English": "Adequate liver function, as evidenced by a serum bilirubin taken during the certain adminitration <=1.5 times of the upper limit of the normal range, ALT and AST <=3 times of the upper limit of the normal range;",
        "comments": "modified|为了测评的可执行性，去掉了时间的限制：筛选期间->某次就医期间"
    }

    # 获取所有肝功能测试Observation
    observations = filter_resources_without_reference_date_system(fhir_service_base_url)

    # 按患者分组观察结果
    patient_observations = {}
    for obs in observations:
        patient_ref = obs.get('subject', {}).get('reference', '')
        if not patient_ref.startswith('Patient/'):
