        meets_criteria = False

        for obs in obs_list:
            code = obs.get('code', {}).get('coding', [{}])[0].get('code', '')
            value = obs.get('valueQuantity', {}).get('value')

            # 获取参考范围上限
            upper_limit = None
            for ref_range in obs.get('referenceRange', []):
