    try:
        data = requests.get(url).json()
        return data['targetId']
    except:
        return None

def filter_resources_without_reference_date_system(fhir_service_base_url):
    # 查询符合Profile的Observation资源
    profile_url = "http://localhost:3456/api/terminology/Profile/cnwqk715-NeoplasmStatus"
    search_url = f"{fhir_service_base_url}/Observation?_profile={profile_url}"

    try:
        response = requests.get(search_url)
        if response.status_code != 200:
            return []

        bundle = response.json()
        observations = []

        # 处理分页
        while bundle:
            if 'entry' in bundle:
                for entry in bundle['entry']:
                    resource = entry.get('resource', {})
                    # 检查是否符合肿瘤侵及状态条件
                    if (resource.get('resourceType') == 'Observation' and
                        'component' in resource):

                        # 检查下腔静脉和门静脉是否都未侵及
                        inferior_vena_cava_infiltrated = None
                        portal_vein_infiltrated = None

                        for component in resource['component']:
                            code = component.get('code', {})
                            coding = code.get('coding', [{}])[0]
                            system = coding.get('system', '')
                            code_value = coding.get('code', '')

                            if (system == "http://localhost:3456/api/terminology/CodeSystem/cnwqk715-InfiltrationSiteCS" and
                                code_value == "inferior_vena_cava"):
                                value_coding = component.get('valueCodeableConcept', {}).get('coding', [{}])[0]
                                if value_coding.get('code') == 'no':
                                    inferior_vena_cava_infiltrated = False
                                elif value_coding.get('code') == 'yes':
                                    inferior_vena_cava_infiltrated = True

                            elif (system == "http://localhost:3456/api/terminology/CodeSystem/cnwqk715-InfiltrationSiteCS" and
                                  code_value == "portal_vein"):
                                value_coding = component.get('valueCodeableConcept', {}).get('coding', [{}])[0]
                                if value_coding.get('code') == 'no':
                                    portal_vein_infiltrated = False
                                elif value_coding.get('code') == 'yes':
                                    portal_vein_infiltrated = True

                        # 如果两个血管都未侵及，则保留该Observation
                        if inferior_vena_cava_infiltrated is False and portal_vein_infiltrated is False:
                            observations.append(resource)

            # 检查是否有下一页
            next_link = None
            for link in bundle.get('link', []):
                if link.get('relation') == 'next':
                    next_link = link.get('url')
