# 2024-08-30 GPT-4o 本代码用于从临床文本中提取窒息缺氧史信息并生成FHIR Condition资源Bundle
import uuid
import re
from datetime import datetime

class FHIRResourceBundleGenerator:
    def __init__(self, fhir_api_base: str):
        self.fhir_api_base = fhir_api_base

    def parse_clinical_text_to_fhir_bundle(self, patient_id, case_reports, ai_algorithm_type="nlp"):
        # 定义否定词列表和作用窗口大小（词数）
        negation_words = ["无", "否", "否认", "未", "没有", "不", "未见", "未发现", "排除", "拒绝"]
        window_size = 5  # 否定词作用窗口大小
        keywords = ["窒息", "缺氧"]

        conditions = []

        for report in case_reports:
            text = report.get("text", "")
            timestamp = report.get("timestamp", "")

            # 预处理文本：去除多余空格
            text = re.sub(r'\s+', ' ', text).strip()

            # 分割文本成句子
            sentences = re.split(r'[。！？；，\.!?;]', text)

            for sentence in sentences:
                sentence = sentence.strip()
                if not sentence:
                    continue

                # 检查句子中是否包含关键词
                found_keywords = []
                for kw in keywords:
                    if kw in sentence:
                        found_keywords.append(kw)

                if found_keywords:
                    # 检查否定词：在句子中查找否定词
                    has_negation = False
                    words = list(re.finditer(r'\w+', sentence))  # 简单分词
                    word_list = [w.group() for w in words]

                    for i, word in enumerate(word_list):
                        if word in negation_words:
                            # 检查否定词前后的窗口
                            start = max(0, i - window_size)
                            end = min(len(word_list), i + window_size + 1)
                            context = word_list[start:end]

                            # 如果窗口中有关键词，则认为是否定
                            if any(kw in context for kw in keywords):
                                has_negation = True
                                break

                    if not has_negation:
                        # 创建Condition资源
                        condition = self._create_condition(patient_id, found_keywords, sentence, timestamp)
                        conditions.append(condition)

        # 构建Bundle
        bundle = {
            "resourceType": "Bundle",
            "type": "transaction",
            "total": len(conditions),
            "entry": []
        }

        for condition in conditions:
            entry = {
                "resource": condition,
                "request": {
                    "method": "POST",
                    "url": "Condition"
                }
            }
            bundle["entry"].append(entry)

        return bundle

    def _create_condition(self, patient_id, keywords, sentence, timestamp):
        codings = []
        for kw in keywords:
            if kw == "窒息":
                code = "suffocation"
                display = "窒息"
            else:  # "缺氧"
                code = "hypoxia"
                display = "缺氧"
            coding = {
                "system": "http://localhost:3456/api/terminology/CodeSystem/cnwqk765-history-codesystem",
                "code": code,
                "display": display
            }
            codings.append(coding)

        # 创建CodeableConcept
        codeable_concept = {
            "coding": codings,
            "text": "、".join(keywords)
        }

        condition_id = str(uuid.uuid1())

        # 确保timestamp格式正确
        try:
            recorded_date = datetime.fromisoformat(timestamp.replace('Z', '+00:00')).isoformat()
        except:
            recorded_date = timestamp  # 保持原样，如果格式错误

        condition = {
            "resourceType": "Condition",
            "id": condition_id,
            "meta": {
                "profile": [
                    "http://localhost:3456/api/terminology/Profile/cnwqk765-condition-history"
                ]
            },
            "text": {
                "status": "generated",
                "div": f"<div xmlns='http://www.w3.org/1999/xhtml'>文本摘录: {sentence}</div>"
            },
            "code": codeable_concept,
            "subject": {
                "reference": f"Patient/{patient_id}"
            },
            "recordedDate": recorded_date
        }

